class Solver {

    private boolean check(char[] S, char[] T, int si, int sj) {
        int N = S.length;
        for (int i = 0; i < N; i++) {
            if (S[(si + i) % N] !=  T[(sj + i) % N]) {
                return false;
            }
        }
        return true;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        char[] S = sc.next().toCharArray();
