        boolean rotatable = false;
        for (int i = 0; i < S.length; i++) {
            char ch = S[i];
            // find ch
            for (int j = 0; j < T.length; j++) {
                if (ch == T[j]) {
                    // start check
                    if (check(S, T, i, j)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }

        System.out.println("No");

        return;
    }

}

