class Main {

	private static int f(long a) {
		int count = 0;
		while (a > 0) {
			count++;
			a /= 10;
		}

		return count;
	}

	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		long N = sc.nextLong();

		int a = f(N);
		for (long i = 1; i * i <= N; i++) {
			if (N % i != 0) continue;
			int x = Math.max(f(i), f(N / i));
			a = Math.min(a, x);
		}

		System.out.println(a);
	}
}

